import numpy as np
def cosine_lr(step, total, lr_max, warmup):
    if step < warmup:
        return lr_max * (step + 1) / warmup
    t = (step - warmup) / max(1, total - warmup)
    return 0.5 * lr_max * (1 + np.cos(np.pi * t))

print([round(float(cosine_lr(s, 100, 0.1, 10)), 4) for s in (0, 10, 99)])
